const periodEnd = new Date();
periodEnd.setUTCMilliseconds(0);

const periodStart = new Date(periodEnd);
periodStart.setUTCDate(periodStart.getUTCDate() - 7);

return [
  {
    json: {
      repository: "Neiskkk/ITMOv2",
      period_start: periodStart.toISOString().replace(".000Z", "Z"),
      period_end: periodEnd.toISOString().replace(".000Z", "Z")
    }
  }
];

const period = $('Report period').first().json;

const sources = [
  { type: "bug", node: "Get weekly bugs" },
  { type: "task", node: "Get weekly tasks" },
  { type: "feature", node: "Get weekly features" },
  { type: "needs-triage", node: "Get weekly triage" }
];

const byType = {};
const issuesById = new Map();

for (const source of sources) {
  const response = $(source.node).first().json;

  if (response.incomplete_results || response.items.length !== response.total_count) {
    throw new Error("Получены не все Issues для " + source.type);
  }

  byType[source.type] = response.items.length;

  for (const issue of response.items) {
    issuesById.set(issue.id, issue);
  }
}

const authorCounts = new Map();

for (const issue of issuesById.values()) {
  const author = issue.user.login;
  authorCounts.set(author, (authorCounts.get(author) ?? 0) + 1);
}

const byAuthor = Array.from(authorCounts, ([author, count]) => ({
  author,
  count
}));

return [
  {
    json: {
      ...period,
      total: issuesById.size,
      by_type: byType,
      by_author: byAuthor
    }
  }
];

const stats = $('Calculate weekly delta').first().json;
const aiComment = $input.first().json.text?.trim();
if (!aiComment) throw new Error("AI-комментарий не получен");

const escapeHtml = value => String(value)
  .replaceAll("&", "&amp;")
  .replaceAll("<", "&lt;")
  .replaceAll(">", "&gt;")
  .replaceAll('"', "&quot;")
  .replaceAll("'", "&#39;");

const formatDelta = value =>
  value == null ? "—" : value > 0 ? "+" + value : String(value);

const dateFormat = new Intl.DateTimeFormat("ru-RU", {
  timeZone: "Europe/Moscow",
  dateStyle: "medium",
  timeStyle: "short"
});

const typeRows = Object.entries(stats.by_type)
  .map(([type, count]) => `<tr>
    <td>${escapeHtml(type)}</td>
    <td>${count}</td>
    <td>${formatDelta(stats.delta.by_type[type])}</td>
  </tr>`).join("");

const currentAuthors = new Map(
  stats.by_author.map(({ author, count }) => [author, count])
);

const authorRows = stats.delta.by_author
  .map(({ author, count }) => `<tr>
    <td>${escapeHtml(author)}</td>
    <td>${currentAuthors.get(author) ?? 0}</td>
    <td>${formatDelta(count)}</td>
  </tr>`).join("") ||
  '<tr><td colspan="3">Обращений за период нет</td></tr>';

const start = dateFormat.format(new Date(stats.period_start));
const end = dateFormat.format(new Date(stats.period_end));

const comparison = stats.previous
  ? `Сравнение с записью за ${escapeHtml(stats.previous.week_key)}.
     Всего за предыдущую неделю: ${stats.previous.total}.`
  : "Предыдущая неделя ещё не сохранена. Δ не рассчитана.";

const html = `
<html>
<body style="font-family:Arial,sans-serif;line-height:1.5">
  <h2>Статистика GitHub Issues</h2>
  <p>Репозиторий: <b>${escapeHtml(stats.repository)}</b></p>
  <p>Период: ${start} — ${end} (МСК)</p>
  <p><b>Всего обращений: ${stats.total}</b></p>
  <p>${comparison}</p>
  <p><b>Δ общего количества: ${formatDelta(stats.delta.total)}</b></p>

  <h3>По типам</h3>
  <table border="1" cellspacing="0" cellpadding="8">
    <tr>
      <th>Тип</th>
      <th>Количество</th>
      <th>Δ к прошлой неделе</th>
    </tr>
    ${typeRows}
  </table>

  <h3>По авторам</h3>
  <table border="1" cellspacing="0" cellpadding="8">
    <tr>
      <th>Автор</th>
      <th>Количество</th>
      <th>Δ к прошлой неделе</th>
    </tr>
    ${authorRows}
  </table>
  <p>Δ — текущее количество минус количество предыдущей недели.</p>
  <h3>AI-комментарий недели</h3>
  <p>${escapeHtml(aiComment).replaceAll("\n", "<br>")}</p>
</body>
</html>`;

return [{
  json: {
    ...stats,
    subject: `Еженедельная статистика Issues — ${stats.repository}`,
    html
  }
}];

const current = $('Aggregate weekly stats').first().json;
const row = $input.first().json;

const previous = row.week_key ? {
  week_key: row.week_key.trim(),
  total: Number(row.total),
  by_type: JSON.parse(row.by_type),
  by_author: JSON.parse(row.by_author),
} : null;

const currentAuthors = new Map(
  current.by_author.map(({ author, count }) => [author, count])
);
const previousAuthors = new Map(
  (previous?.by_author ?? []).map(({ author, count }) => [author, count])
);
const authors = [...new Set([
  ...currentAuthors.keys(), ...previousAuthors.keys()
])].sort();

const delta = {
  total: previous ? current.total - previous.total : null,
  by_type: Object.fromEntries(
    Object.entries(current.by_type).map(([type, count]) => [
      type, previous ? count - (previous.by_type[type] ?? 0) : null
    ])
  ),
  by_author: authors.map(author => ({
    author,
    count: previous
      ? (currentAuthors.get(author) ?? 0) - (previousAuthors.get(author) ?? 0)
      : null
  }))
};

return [{ json: { ...current, previous, delta } }];
